package org.usbworkbench;
import java.io.*;
import java.nio.*;
import java.nio.charset.*;
import java.util.*;
import java.util.zip.GZIPInputStream;
import org.tukaani.xz.XZInputStream;
/** Bounded original USTAR/PAX reader. Never executes members or follows links. */
public final class TarTools {
    public static final class Entry {public final String path;public final long size;public final int type;Entry(String path,long size,int type){this.path=path;this.size=size;this.type=type;}public boolean directory(){return type=='5';}public boolean regular(){return type==0||type=='0'||type=='7';}}
    public interface Visitor {void entry(Entry e,InputStream content)throws IOException;}
    private static String text(byte[] b,int off,int n)throws IOException{int end=off;while(end<off+n&&b[end]!=0)end++;try{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b,off,end-off)).toString();}catch(CharacterCodingException e){throw new IOException("TAR_PATH");}}
    private static long octal(byte[] b,int off,int n)throws IOException{long value=0;boolean ended=false;if((b[off]&128)!=0)throw new IOException("TAR_NUMBER");for(int i=off;i<off+n;i++){int c=b[i]&255;if(c==0||c==' '){if(value>0)ended=true;continue;}if(c<'0'||c>'7'||ended||value>(Long.MAX_VALUE-7)/8)throw new IOException("TAR_NUMBER");value=value*8+c-'0';}return value;}
    private static boolean zero(byte[] b){for(byte v:b)if(v!=0)return false;return true;}
    private static String path(String name)throws IOException{while(name.startsWith("./"))name=name.substring(2);try{String result=ZipTools.safePath(name);if(result.split("/").length>32)throw new IOException("TAR_PATH");return result;}catch(IOException e){throw new IOException("TAR_PATH");}}
    private static final class Bounded extends InputStream {final InputStream in;long remaining,done;final DiskTools.Progress p;Bounded(InputStream in,long n,DiskTools.Progress p){this.in=in;remaining=n;this.p=p;}public int read()throws IOException{byte[] b=new byte[1];return read(b,0,1)<0?-1:b[0]&255;}public int read(byte[] b,int off,int n)throws IOException{if(n==0)return 0;if(remaining==0)return -1;int r=in.read(b,off,(int)Math.min(n,remaining));if(r<0)throw new IOException("TAR_SHORT");if(r==0)throw new IOException("SOURCE_STALLED");remaining-=r;done+=r;p.update(done,-1);return r;}public void close(){} }
    private static void drain(InputStream in,long count)throws IOException{byte[] b=new byte[16384];while(count>0){int n=in.read(b,0,(int)Math.min(b.length,count));if(n<0)throw new IOException("TAR_SHORT");if(n==0)throw new IOException("SOURCE_STALLED");count-=n;}}
    private static Map<String,String> pax(byte[] bytes)throws IOException{Map<String,String> fields=new HashMap<>();int at=0;while(at<bytes.length){int space=at;while(space<bytes.length&&bytes[space]!=' ')space++;if(space==bytes.length||space-at>9)throw new IOException("TAR_PAX");int length;try{length=Integer.parseInt(new String(bytes,at,space-at,StandardCharsets.US_ASCII));}catch(NumberFormatException e){throw new IOException("TAR_PAX");}if(length<=space-at+2||length>bytes.length-at||bytes[at+length-1]!='\n')throw new IOException("TAR_PAX");String pair=text(bytes,space+1,at+length-space-2);int eq=pair.indexOf('=');if(eq<=0)throw new IOException("TAR_PAX");String key=pair.substring(0,eq);if(key.startsWith("GNU.sparse")||fields.put(key,pair.substring(eq+1))!=null)throw new IOException("TAR_PAX");at+=length;}return fields;}
    public static int scan(InputStream source,Visitor visitor,long maxBytes,int maxEntries,DiskTools.Progress p)throws IOException{
        PushbackInputStream raw=new PushbackInputStream(source,6);byte[] magic=new byte[6];int peek=0;while(peek<6){int n=raw.read(magic,peek,6-peek);if(n<0)break;if(n==0)throw new IOException("SOURCE_STALLED");peek+=n;}raw.unread(magic,0,peek);InputStream decoded=peek>=2&&(magic[0]&255)==31&&(magic[1]&255)==139?new GZIPInputStream(raw,16384):peek==6&&Arrays.equals(magic,new byte[]{(byte)253,55,122,88,90,0})?new XZInputStream(raw,32768):raw;
        try(InputStream in=decoded){byte[] header=new byte[512];long declared=0;int count=0,metadata=0;String nextName=null;Map<String,String> nextPax=Collections.emptyMap();Set<String> names=new HashSet<>();
            while(true){p.update(declared,-1);try{DiskTools.readFully(in,header,512);}catch(IOException e){throw new IOException("TAR_SHORT",e);}if(zero(header)){byte[] second=new byte[512];DiskTools.readFully(in,second,512);if(!zero(second))throw new IOException("TAR_TRAILING");int n,total=0;byte[] tail=new byte[4096];while((n=in.read(tail))!=-1){if(n==0)throw new IOException("SOURCE_STALLED");total+=n;if(total>1048576)throw new IOException("TAR_LIMIT");for(int i=0;i<n;i++)if(tail[i]!=0)throw new IOException("TAR_TRAILING");}if(count==0)throw new IOException("NOT_TAR");return count;}
                long checksum=octal(header,148,8),sum=0;for(int i=0;i<512;i++)sum+=i>=148&&i<156?32:header[i]&255;if(checksum!=sum)throw new IOException("TAR_CHECKSUM");long size=octal(header,124,12);int type=header[156]&255;
                String name=text(header,0,100),prefix=text(header,345,155);boolean ustar=new String(header,257,5,StandardCharsets.US_ASCII).equals("ustar");if(ustar&&!prefix.isEmpty())name=prefix+"/"+name;
                if(type=='L'||type=='x'||type=='g'){if(++metadata>maxEntries||size>65536)throw new IOException("TAR_LIMIT");byte[] data=new byte[(int)size];DiskTools.readFully(in,data,data.length);drain(in,(512-size%512)%512);if(type=='g')throw new IOException("TAR_PAX");if(type=='L'){if(nextName!=null)throw new IOException("TAR_PAX");nextName=text(data,0,data.length);if(nextName.endsWith("\n"))nextName=nextName.substring(0,nextName.length()-1);}else nextPax=pax(data);continue;}
                if(nextName!=null){name=nextName;nextName=null;}if(nextPax.containsKey("path"))name=nextPax.get("path");if(nextPax.containsKey("size")){try{size=Long.parseLong(nextPax.get("size"));}catch(NumberFormatException e){throw new IOException("TAR_PAX");}}nextPax=Collections.emptyMap();if(size<0||size>maxBytes-declared)throw new IOException("TAR_LIMIT");declared+=size;
                if((name.equals(".")||name.equals("./"))&&type=='5'&&size==0)continue;if(++count>maxEntries)throw new IOException("TAR_LIMIT");String safe=path(name);if(!names.add(safe.toLowerCase(Locale.ROOT)))throw new IOException("TAR_DUPLICATE");if(type=='5'&&size!=0)throw new IOException("TAR_PATH");Bounded part=new Bounded(in,size,p);visitor.entry(new Entry(safe,size,type),part);drain(part,part.remaining);drain(in,(512-size%512)%512);
            }
        }
    }
    public static long extract(InputStream source,ZipTools.Sink sink,long maxBytes,int maxEntries,DiskTools.Progress p)throws IOException{long[] expanded={0};scan(source,(entry,in)->{if(entry.directory())sink.directory(entry.path);else if(entry.regular()){int slash=entry.path.lastIndexOf('/');if(slash>0)sink.directory(entry.path.substring(0,slash));try(OutputStream out=sink.file(entry.path)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){p.update(expanded[0],-1);out.write(b,0,n);expanded[0]+=n;}}}else throw new IOException("TAR_LINK");},maxBytes,maxEntries,p);p.update(expanded[0],expanded[0]);return expanded[0];}
}
